import java.io.*;

public class Main {
    static final long MOD = 1_000_000_007L;
    static int k;
    static int[] factorial;
    static int[] inverseFactorial;
    static long inverseK;

    static long modPow(long base, long exponent) {
        long result = 1;
        base %= MOD;
        while (exponent > 0) {
            if ((exponent & 1) != 0) {
                result = result * base % MOD;
            }
            base = base * base % MOD;
            exponent >>= 1;
        }
        return result;
    }

    static long sumAtMost(long limit) {
        int nonOverlapping = (int) Math.min((long) k, limit);
        long result = 0;
        long falling = 1;
        long power = modPow(k, limit - 1);

        for (int p = 1; p <= nonOverlapping; p++) {
            falling = falling * (k - p + 1L) % MOD;
            long term = falling * falling % MOD * power % MOD;
            result += term;
            if (result >= MOD) result -= MOD;
            power = power * inverseK % MOD;
        }

        if (limit < k) {
            int t = (int) limit;
            for (int p = t + 1; p <= k; p++) {
                int q = p - t;

                long first = (long) factorial[k] * inverseFactorial[k - q] % MOD;
                long side = (long) factorial[k - q] * inverseFactorial[k - p] % MOD;
                long term = first * side % MOD * side % MOD;

                result += term;
                if (result >= MOD) result -= MOD;
            }
        }

        return result;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        k = fs.nextInt();
        long w = fs.nextLong();

        factorial = new int[k + 1];
        inverseFactorial = new int[k + 1];

        factorial[0] = 1;
        for (int i = 1; i <= k; i++) {
            factorial[i] = (int) ((long) factorial[i - 1] * i % MOD);
        }

        inverseFactorial[k] = (int) modPow(factorial[k], MOD - 2);
        for (int i = k; i > 0; i--) {
            inverseFactorial[i - 1] =
                    (int) ((long) inverseFactorial[i] * i % MOD);
        }

        inverseK = modPow(k, MOD - 2);

        long answer = sumAtMost(w) - sumAtMost(w - 1) + modPow(k, w);
        answer %= MOD;
        if (answer < 0) answer += MOD;

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream input;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer;
        private int length;

        FastScanner(InputStream input) {
            this.input = input;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = input.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

