public class Main {
    static final long MOD = 1_000_000_007L;
    static int k;
    static long[] fact;
    static long[] invFact;
    static long invK;

    static long modPow(long base, long exponent) {
        long result = 1;
        base %= MOD;
        while (exponent > 0) {
            if ((exponent & 1) != 0) {
                result = result * base % MOD;
            }
            base = base * base % MOD;
            exponent >>= 1;
        }
        return result;
    }

    static long countAtMost(long x) {
        long result;

        if (k == 1) {
            result = x % MOD;
        } else {
            long geometric = (modPow(k, x) - 1 + MOD) % MOD;
            geometric = geometric * k % MOD;
            geometric = geometric * modPow(k - 1L, MOD - 2) % MOD;
            result = geometric;
        }

        int limit = (int) Math.min((long) k, x);
        long falling = k;
        long power = modPow(k, x - 1);

        for (int d = 1; d <= limit; d++) {
            long term = falling * falling % MOD * power % MOD;
            result += term;
            if (result >= MOD) result -= MOD;

            if (d < limit) {
                falling = falling * (k - d) % MOD;
                power = power * invK % MOD;
            }
        }

        if (x < k) {
            int xi = (int) x;
            for (int d = xi + 1; d <= k; d++) {
                int a = k - d;

                long term = fact[k] * invFact[a] % MOD;
                term = term * fact[a + xi] % MOD;
                term = term * invFact[a] % MOD;

                result += term;
                if (result >= MOD) result -= MOD;
            }
        }

        return result;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        k = fs.nextInt();
        long w = fs.nextLong();

        fact = new long[k + 1];
